/* أسئلة المدرب الذكي التفاعلي داخل شرح الدرس: r ربط بالدرس السابق، s رمز القانون ووحدته، i استنتاج من القانون، m ملخص الدرس. الإجابة الصحيحة أولا وتخلط عند العرض، و w سبب التصحيح */
window.COACHQ={"0-1":{"r":{"q":"أي مما يلي يمكن قياسه بأداة؟","o":["طول الطاولة","جمال اللوحة","الشجاعة","الذكاء"],"a":0,"say":"كل ما يقاس بمقدار ووحدة كمية فيزيائية، واليوم نتعرف على أنواعها ووحداتها.","w":"الطول كمية فيزيائية نقيسها بالمسطرة، أما الباقي فلا يقاس بأداة"},"s":{"q":"في قانون السرعة `v = d / t`، ماذا يمثل الرمز `v`، وما وحدة قياسه؟","o":["السرعة، ووحدتها m/s","السرعة، ووحدتها m","المسافة، ووحدتها m/s","الزمن، ووحدته s"],"a":0,"law":"v = d / t","w":"السرعة هي المسافة على الزمن، فوحدتها المتر على الثانية"},"i":{"q":"من القانون v = d / t، إذا بقي الزمن ثابتا، ما العلاقة بين السرعة والمسافة؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"المسافة في البسط، فكلما زادت المسافة زادت السرعة عند ثبات الزمن"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الكميات الفيزيائية وأنظمة القياس في جملة واحدة، فماذا تقول؟","o":["الكميات الأساسية مثل الطول والكتلة والزمن لا تشتق من غيرها، والمشتقة مثل السرعة تعرف بدلالتها، ووحدة الكتلة الدولية الكيلوجرام.","الكميات المشتقة مثل الطول والكتلة والزمن لا تشتق من غيرها، والأساسية مثل السرعة تعرف بدلالتها، ووحدة الكتلة الدولية الكيلوجرام.","الكميات الأساسية مثل الطول والكتلة والزمن لا تشتق من غيرها، والمشتقة مثل السرعة تعرف بدلالتها، ووحدة الكتلة الدولية الجرام.","الكميات الأساسية مثل الطول والكتلة والسرعة لا تشتق من غيرها، والمشتقة مثل المساحة تعرف بدلالتها، ووحدة الكتلة الدولية الكيلوجرام."],"a":0},"x":"law"},"0-2":{"r":{"q":"ما وحدة الطول الأساسية في النظام الدولي SI؟","o":["المتر","السنتيمتر","الكيلومتر","المليمتر"],"a":0,"say":"واليوم نتعلم كيف نحول بين المتر والسنتيمتر والكيلومتر وغيرها.","w":"المتر هو وحدة الطول الأساسية في النظام الدولي"},"s":{"q":"أي عبارة تصف قانون تحويل السرعة `v(m/s) = v(km/h) × 5 / 18`؟","o":["للتحويل من km/h إلى m/s نضرب السرعة في 5 على 18","للتحويل من km/h إلى m/s نضرب السرعة في 18 على 5","للتحويل من km/h إلى m/s نضيف 5 على 18 إلى السرعة","للتحويل من m/s إلى km/h نضرب السرعة في 5 على 18"],"a":0,"law":"v(m/s) = v(km/h) × 5 / 18","w":"الكيلومتر 1000 متر والساعة 3600 ثانية، و 1000 على 3600 تساوي 5 على 18","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون v = d / t، كيف نحسب الزمن؟","o":["t = d / v","t = d·v","t = v / d","t = d − v"],"a":0,"t":3,"w":"نا نضرب الطرفين في t ثم نقسم على v فنحصل على t = d / v"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس التحويل بين الوحدات والتحقق من صحة القوانين في جملة واحدة، فماذا تقول؟","o":["من الوحدة الكبيرة إلى الصغيرة نضرب في معامل التحويل، ومن الصغيرة إلى الكبيرة نقسم، ويصح القانون إذا تساوت وحدتا طرفيه.","من الوحدة الكبيرة إلى الصغيرة نقسم على معامل التحويل، ومن الصغيرة إلى الكبيرة نضرب، ويصح القانون إذا تساوت وحدتا طرفيه.","من الوحدة الكبيرة إلى الصغيرة نضرب في معامل التحويل، ومن الصغيرة إلى الكبيرة نقسم، ويصح القانون إذا تساوت أرقام طرفيه.","من الوحدة الكبيرة إلى الصغيرة نجمع معامل التحويل، ومن الصغيرة إلى الكبيرة نطرحه، ويصح القانون إذا تساوت وحدتا طرفيه."],"a":0},"x":"law"},"0-4":{"r":{"q":"لماذا نتحقق من صحة القانون بالوحدات؟","o":["لأن وحدة طرفي القانون يجب أن تتساوى","لأن الأرقام يجب أن تتساوى","لأن الرموز يجب أن تتساوى","لا داعي للتحقق"],"a":0,"say":"والكميات لا تختلف في وحداتها فقط، فبعضها يحتاج اتجاها أيضا، وهذا موضوع درسنا اليوم.","w":"القانون الصحيح تتساوى فيه وحدتا الطرفين"},"s":{"q":"في قانون جيب التمام للمحصلة `C² = A² + B² + 2AB·cos θ`، ماذا يمثل الرمز `C`، وما وحدة قياسه؟","o":["المحصلة، ووحدتها وحدة المتجهين نفسها","الزاوية، ووحدتها الدرجة","المحصلة، ووحدتها الدرجة","المتجه الأول، ووحدته المتر دائما"],"a":0,"law":"C² = A² + B² + 2AB·cos θ","w":"C هي المحصلة، ووحدتها وحدة المتجهين نفسها"},"i":{"q":"من القانون C² = A² + B² + 2AB·cos θ، إذا بقي المتجهان ثابتين وزادت الزاوية بينهما من `0°` إلى `180°`، كيف تتغير المحصلة؟","o":["تقل","تزداد","لا تتغير","تتضاعف"],"a":0,"t":1,"w":"كلما زادت الزاوية قلت قيمة cos θ فتقل المحصلة"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الكميات القياسية والمتجهة وجمع المتجهات في جملة واحدة، فماذا تقول؟","o":["القياسية لها مقدار فقط، والمتجهة لها مقدار واتجاه، والمحصلة تعتمد على الزاوية بين المتجهين.","القياسية لها مقدار واتجاه، والمتجهة لها مقدار فقط، والمحصلة تعتمد على الزاوية بين المتجهين.","القياسية لها مقدار فقط، والمتجهة لها مقدار واتجاه، والمحصلة تساوي مجموع المتجهين دائما.","القياسية لها مقدار فقط، والمتجهة لها مقدار واتجاه، والمحصلة لا تتأثر بالزاوية بين المتجهين."],"a":0},"x":"law"},"0-5":{"r":{"q":"ما الكمية المتجهة؟","o":["كمية لها مقدار واتجاه","كمية لها مقدار فقط","كمية بلا وحدة","كمية ثابتة دائما"],"a":0,"say":"تعلمنا جمع متجهين في محصلة واحدة، واليوم نعكس العملية فنحلل المتجه إلى مركبتين.","w":"الكمية المتجهة تحدد بمقدار واتجاه معا"},"s":{"q":"أي عبارة تصف قانون المركبة السينية `Ax = A·cos θ`؟","o":["المركبة السينية تساوي مقدار المتجه في جيب تمام الزاوية مع المحور السيني","المركبة السينية تساوي مقدار المتجه في جيب الزاوية مع المحور السيني","المركبة السينية تساوي مقدار المتجه مقسوما على جيب تمام الزاوية مع المحور السيني","المركبة السينية تساوي مقدار المتجه في جيب تمام الزاوية مع المحور الصادي"],"a":0,"law":"Ax = A·cos θ","w":"المركبة السينية مجاورة للزاوية، فنستخدم جيب التمام","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون Ax = A·cos θ، كيف نحسب مقدار المتجه A؟","o":["A = Ax / cos θ","A = Ax·cos θ","A = cos θ / Ax","A = Ax − cos θ"],"a":0,"t":3,"w":"نا نقسم الطرفين على cos θ فنحصل على A = Ax / cos θ"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس تحليل المتجهات في جملة واحدة، فماذا تقول؟","o":["نحلل المتجه إلى مركبة سينية Ax = A·cos θ ومركبة صادية Ay = A·sin θ، والزاوية تقاس من المحور السيني.","نحلل المتجه إلى مركبة سينية Ax = A·sin θ ومركبة صادية Ay = A·cos θ، والزاوية تقاس من المحور السيني.","نحلل المتجه إلى مركبة سينية Ax = A·cos θ ومركبة صادية Ay = A·sin θ، والزاوية تقاس من المحور الصادي.","نحلل المتجه إلى مركبة سينية Ax = A·cos θ ومركبة صادية Ay = A·cos θ، والزاوية تقاس من المحور السيني."],"a":0},"x":"law"},"0-6":{"r":{"q":"المركبة السينية لمتجه A يصنع زاوية θ مع المحور السيني هي:","o":["A·cos θ","A·sin θ","A·tan θ","A / cos θ"],"a":0,"say":"والمركبتان نكتبهما اليوم بمتجهات الوحدة î و ĵ، ثم نضرب المتجهات.","w":"المركبة السينية هي المجاورة للزاوية، فتساوي A·cos θ"},"s":{"q":"في قانون الضرب القياسي `A·B = |A||B|·cos θ`، ماذا يمثل الرمز `θ`، وما وحدة قياسه؟","o":["الزاوية بين المتجهين، ووحدتها الدرجة","الزاوية مع المحور السيني، ووحدتها الدرجة","ناتج الضرب، ووحدته الدرجة","طول المتجه، ووحدته المتر"],"a":0,"law":"A·B = |A||B|·cos θ","w":"θ في الضرب القياسي هي الزاوية بين المتجهين"},"i":{"q":"من القانون A·B = |A||B|·cos θ، إذا بقي المقداران ثابتين، ما العلاقة بين ناتج الضرب و cos θ؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"عند ثبات المقدارين يتغير الناتج بتغير cos θ في نفس الاتجاه"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس متجهات الوحدة وضرب المتجهات في جملة واحدة، فماذا تقول؟","o":["متجهات الوحدة مقدارها 1 وتحدد الاتجاه، والضرب القياسي للمتجهات كمية قياسية A·B = |A||B|·cos θ.","متجهات الوحدة مقدارها صفر وتحدد الاتجاه، والضرب القياسي للمتجهات كمية قياسية A·B = |A||B|·cos θ.","متجهات الوحدة مقدارها 1 وتحدد الاتجاه، والضرب القياسي للمتجهات كمية متجهة A·B = |A||B|·cos θ.","متجهات الوحدة مقدارها 1 وتحدد الاتجاه، والضرب القياسي للمتجهات كمية قياسية A·B = |A||B|·sin θ."],"a":0},"x":"law"},"1-1":{"r":{"q":"ناتج الضرب القياسي لمتجهين يكون:","o":["كمية قياسية","كمية متجهة","متجه وحدة","صفرا دائما"],"a":0,"say":"وفي الحركة نجد كميات قياسية وأخرى متجهة، مثل المسافة والإزاحة، وهي موضوع درسنا اليوم.","w":"الضرب القياسي ينتج مقدارا فقط بلا اتجاه"},"s":{"q":"أي عبارة تصف قانون التسارع `a = (Vf − Vi) / t`؟","o":["التسارع يساوي التغير في السرعة مقسوما على الزمن","التسارع يساوي مجموع السرعتين مقسوما على الزمن","التسارع يساوي التغير في السرعة مضروبا في الزمن","التسارع يساوي التغير في الإزاحة مقسوما على الزمن"],"a":0,"law":"a = (Vf − Vi) / t","w":"التسارع معدل تغير السرعة بالنسبة للزمن","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون a = (Vf − Vi) / t، كيف نحسب الزمن؟","o":["t = (Vf − Vi) / a","t = a·(Vf − Vi)","t = a / (Vf − Vi)","t = Vf − Vi − a"],"a":0,"t":3,"w":"نا نضرب الطرفين في t ثم نقسم على a فنحصل على t = (Vf − Vi) / a"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس المسافة والإزاحة والسرعة والتسارع في جملة واحدة، فماذا تقول؟","o":["المسافة قياسية والإزاحة متجهة، والسرعة المتوسطة الإزاحة على الزمن، والتسارع التغير في السرعة على الزمن.","المسافة متجهة والإزاحة قياسية، والسرعة المتوسطة الإزاحة على الزمن، والتسارع التغير في السرعة على الزمن.","المسافة قياسية والإزاحة متجهة، والسرعة المتوسطة الزمن على الإزاحة، والتسارع التغير في السرعة على الزمن.","المسافة قياسية والإزاحة متجهة، والسرعة المتوسطة الإزاحة على الزمن، والتسارع التغير في المسافة على الزمن."],"a":0},"x":"req"},"1-2":{"r":{"q":"ما التسارع؟","o":["التغير في السرعة بالنسبة للزمن","المسافة بالنسبة للزمن","الإزاحة مضروبة في الزمن","السرعة الثابتة"],"a":0,"say":"واليوم نستخدم التسارع الثابت لنحسب السرعة والإزاحة في أي لحظة.","w":"التسارع هو معدل تغير السرعة بالنسبة للزمن"},"s":{"q":"في قانون السرعة النهائية `Vf = Vi + a·t`، ماذا يمثل الرمز `Vi`، وما وحدة قياسه؟","o":["السرعة الابتدائية، ووحدتها m/s","السرعة النهائية، ووحدتها m/s","السرعة الابتدائية، ووحدتها m/s²","التسارع، ووحدته m/s"],"a":0,"law":"Vf = Vi + a·t","w":"Vi هي السرعة في بداية الحركة وتقاس بالمتر على الثانية"},"i":{"q":"من القانون Vf = Vi + a·t لجسم يبدأ من السكون، إذا بقي التسارع ثابتا، ما العلاقة بين السرعة النهائية والزمن؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"عند البدء من السكون Vf = a·t، فتزيد السرعة بزيادة الزمن"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس معادلات الحركة بتسارع ثابت في جملة واحدة، فماذا تقول؟","o":["معادلات تربط السرعة والإزاحة والتسارع والزمن لجسم يتحرك بتسارع ثابت، مثل Vf = Vi + a·t.","معادلات تربط السرعة والإزاحة والتسارع والزمن لجسم يتحرك بتسارع متغير، مثل Vf = Vi + a·t.","معادلات تربط السرعة والإزاحة والتسارع والزمن لجسم يتحرك بسرعة ثابتة، مثل Vf = Vi + a·t.","معادلات تربط السرعة والإزاحة والتسارع والزمن لجسم يتحرك بتسارع ثابت، مثل Vf = Vi − a·t."],"a":0},"x":"law"},"1-3":{"r":{"q":"إذا كان تسارع جسم سالبا فإن سرعته:","o":["تقل","تزداد","تبقى ثابتة","تساوي صفرا"],"a":0,"say":"فما الذي يجعل سرعة الجسم تتغير؟ إنها القوة، وهي موضوع قوانين نيوتن اليوم.","w":"التسارع السالب عكس اتجاه الحركة، فيبطئ الجسم"},"s":{"q":"أي عبارة تصف قانون نيوتن الثاني `F = m·a`؟","o":["القوة المحصلة تساوي الكتلة في التسارع","القوة المحصلة تساوي الكتلة مقسومة على التسارع","القوة المحصلة تساوي الوزن في التسارع","القوة المحصلة تساوي الكتلة في السرعة"],"a":0,"law":"F = m·a","w":"قانون نيوتن الثاني يربط القوة المحصلة بحاصل ضرب الكتلة في التسارع","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون F = m·a، كيف نحسب التسارع؟","o":["a = F / m","a = F·m","a = m / F","a = F − m"],"a":0,"t":3,"w":"نا نقسم الطرفين على m فنحصل على a = F / m"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس القوة وقوانين نيوتن للحركة في جملة واحدة، فماذا تقول؟","o":["القوة دفع أو سحب ووحدتها النيوتن، والجسم يبقى على حالته ما لم تؤثر عليه قوة، والقوة تساوي الكتلة في التسارع.","القوة دفع أو سحب ووحدتها الجول، والجسم يبقى على حالته ما لم تؤثر عليه قوة، والقوة تساوي الكتلة في التسارع.","القوة دفع أو سحب ووحدتها النيوتن، والجسم المتحرك يتوقف وحده دون قوة، والقوة تساوي الكتلة في التسارع.","القوة دفع أو سحب ووحدتها النيوتن، والجسم يبقى على حالته ما لم تؤثر عليه قوة، والقوة تساوي الكتلة في السرعة."],"a":0},"x":"inf"},"1-5":{"r":{"q":"حسب قانون نيوتن الأول، الجسم المتحرك بلا قوة خارجية:","o":["يستمر بسرعة ثابتة","يتوقف تدريجيا","يتسارع","يعود إلى الخلف"],"a":0,"say":"لكن الصندوق على الأرض يتوقف، لأن قوة تعاكس حركته هي قوة الاحتكاك، موضوع درسنا اليوم.","w":"بلا قوة خارجية لا يتغير حال الجسم، فيبقى بسرعة ثابتة"},"s":{"q":"في قانون قوة الاحتكاك الحركي `fk = μk·N`، ماذا يمثل الرمز `μk`، وما وحدة قياسه؟","o":["معامل الاحتكاك الحركي، وليس له وحدة","معامل الاحتكاك الحركي، ووحدته النيوتن N","القوة العمودية، ووحدتها النيوتن N","قوة الاحتكاك، وليس لها وحدة"],"a":0,"law":"fk = μk·N","w":"μk نسبة بين قوتين فليس لها وحدة"},"i":{"q":"من القانون fk = μk·N، إذا بقي معامل الاحتكاك ثابتا، ما العلاقة بين قوة الاحتكاك والقوة العمودية؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"قوة الاحتكاك تساوي μk في N، فتزيد بزيادة القوة العمودية"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الاحتكاك في جملة واحدة، فماذا تقول؟","o":["قوة الاحتكاك تعيق انزلاق سطحين وتعاكس اتجاه الحركة، وتساوي معامل الاحتكاك في القوة العمودية.","قوة الاحتكاك تساعد على انزلاق سطحين وتكون في اتجاه الحركة، وتساوي معامل الاحتكاك في القوة العمودية.","قوة الاحتكاك تعيق انزلاق سطحين وتعاكس اتجاه الحركة، وتساوي معامل الاحتكاك في السرعة.","قوة الاحتكاك تعيق انزلاق سطحين وتعاكس اتجاه الحركة، ومعامل الاحتكاك وحدته النيوتن."],"a":0},"x":"law"},"1-7":{"r":{"q":"اتجاه قوة الاحتكاك دائما:","o":["معاكس لاتجاه حركة الجسم","في اتجاه الحركة","عمودي على السطح","نحو الأعلى"],"a":0,"say":"وعندما تحرك قوة جسما مسافة تبذل شغلا، وهذا موضوع درسنا اليوم.","w":"الاحتكاك يعيق الانزلاق، فيعاكس اتجاه الحركة"},"s":{"q":"أي عبارة تصف قانون الشغل `W = F·x·cos θ`؟","o":["الشغل يساوي القوة في الإزاحة في جيب تمام الزاوية بينهما","الشغل يساوي القوة في الإزاحة في جيب الزاوية بينهما","الشغل يساوي القوة مقسومة على الإزاحة في جيب تمام الزاوية بينهما","الشغل يساوي الكتلة في الإزاحة في جيب تمام الزاوية بينهما"],"a":0,"law":"W = F·x·cos θ","w":"الشغل تبذله القوة في اتجاه الإزاحة فقط، أي القوة في جيب تمام الزاوية","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون W = F·x (القوة في اتجاه الحركة)، كيف نحسب القوة؟","o":["F = W / x","F = W·x","F = x / W","F = W − x"],"a":0,"t":3,"w":"نا نقسم الطرفين على x فنحصل على F = W / x"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الشغل في جملة واحدة، فماذا تقول؟","o":["الشغل ما تبذله قوة لتحرك جسما مسافة في اتجاهها، وهو كمية قياسية وحدتها الجول، وينعدم إذا لم يتحرك الجسم.","الشغل ما تبذله قوة لتحرك جسما مسافة في اتجاهها، وهو كمية متجهة وحدتها النيوتن، وينعدم إذا لم يتحرك الجسم.","الشغل ما تبذله قوة لتحرك جسما مسافة في اتجاهها، وهو كمية قياسية وحدتها الجول، ويبذل حتى لو لم يتحرك الجسم.","الشغل ما تبذله قوة لتحرك جسما مسافة عمودية على اتجاهها، وهو كمية قياسية وحدتها الجول، وينعدم إذا لم يتحرك الجسم."],"a":0},"x":"inf"},"1-8":{"r":{"q":"إذا لم يتحرك الجسم رغم تأثير القوة، فإن الشغل:","o":["يساوي صفرا","يكون أكبر ما يمكن","يساوي القوة","يساوي الوزن"],"a":0,"say":"والشغل المبذول على الجسم يتحول إلى طاقة، وهذا موضوع درسنا اليوم.","w":"الشغل يحتاج إلى إزاحة، فإذا كانت الإزاحة صفرا كان الشغل صفرا"},"s":{"q":"في قانون طاقة الوضع `PE = m·g·h`، ماذا يمثل الرمز `h`، وما وحدة قياسه؟","o":["الارتفاع، ووحدته المتر m","الارتفاع، ووحدته الجول J","عجلة الجاذبية، ووحدتها m/s²","الكتلة، ووحدتها kg"],"a":0,"law":"PE = m·g·h","w":"h هو الارتفاع عن المستوى المرجعي ويقاس بالمتر"},"i":{"q":"من القانون PE = m·g·h، إذا بقيت الكتلة ثابتة، ما العلاقة بين طاقة الوضع والارتفاع؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"h في البسط، فكلما زاد الارتفاع زادت طاقة الوضع"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الطاقة الحركية وطاقة الوضع في جملة واحدة، فماذا تقول؟","o":["الطاقة الحركية بسبب حركة الجسم وتعتمد على كتلته وسرعته، وطاقة الوضع بسبب ارتفاعه، ووحدتهما الجول.","الطاقة الحركية بسبب ارتفاع الجسم وتعتمد على كتلته وسرعته، وطاقة الوضع بسبب حركته، ووحدتهما الجول.","الطاقة الحركية بسبب حركة الجسم وتعتمد على كتلته وسرعته، وطاقة الوضع بسبب ارتفاعه، ووحدتهما النيوتن.","الطاقة الحركية بسبب حركة الجسم وتعتمد على كتلته فقط، وطاقة الوضع بسبب ارتفاعه، ووحدتهما الجول."],"a":0},"x":"law"},"1-9":{"r":{"q":"الطاقة التي يمتلكها جسم بسبب ارتفاعه هي:","o":["طاقة الوضع","الطاقة الحركية","الطاقة الحرارية","الطاقة النووية"],"a":0,"say":"واليوم نرى كيف تتحول طاقة الوضع إلى طاقة حركية دون أن تفنى.","w":"طاقة الوضع تختزن في الجسم بسبب ارتفاعه"},"s":{"q":"أي عبارة تصف قانون حفظ الطاقة `ΔKE + ΔPE = 0`؟","o":["مجموع التغير في الطاقة الحركية والتغير في طاقة الوضع يساوي صفرا","مجموع التغير في الطاقة الحركية والتغير في طاقة الوضع يساوي واحدا","التغير في الطاقة الحركية يساوي التغير في طاقة الوضع بالإشارة نفسها","مجموع الطاقة الحركية وطاقة الوضع يساوي صفرا دائما"],"a":0,"law":"ΔKE + ΔPE = 0","w":"ما تكسبه إحدى الطاقتين تفقده الأخرى، فتبقى الطاقة الميكانيكية ثابتة","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون ΔKE + ΔPE = 0، كيف نحسب التغير في الطاقة الحركية؟","o":["ΔKE = −ΔPE","ΔKE = ΔPE","ΔKE = ΔPE / 2","ΔKE = 0"],"a":0,"t":3,"w":"نا ننقل ΔPE إلى الطرف الآخر فنحصل على ΔKE = −ΔPE"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس حفظ الطاقة في جملة واحدة، فماذا تقول؟","o":["في النظام المعزول الطاقة لا تفنى ولا تستحدث بل تتحول من صورة إلى أخرى، فتبقى الطاقة الميكانيكية ثابتة.","في النظام المعزول الطاقة تفنى تدريجيا ولا تستحدث بل تتحول من صورة إلى أخرى، فتقل الطاقة الميكانيكية.","في النظام المعزول الطاقة لا تفنى ولا تستحدث بل تتحول من صورة إلى أخرى، فتزداد الطاقة الميكانيكية.","في النظام المعزول الطاقة لا تفنى ولا تستحدث بل تتحول من صورة إلى أخرى، فتبقى الطاقة الحركية ثابتة."],"a":0},"x":"law"},"2-1":{"r":{"q":"في النظام المعزول، الطاقة:","o":["لا تفنى ولا تستحدث بل تتحول","تفنى تدريجيا","تستحدث من العدم","تزداد دائما"],"a":0,"say":"ومن صور الطاقة الحرارة، وهي موضوع وحدتنا الجديدة.","w":"في النظام المعزول تتحول الطاقة من صورة إلى أخرى ولا تفنى"},"s":{"q":"في قانون التحويل من سلسيوس إلى كلفن `K = °C + 273`، ماذا يمثل الرمز `K`، وما وحدة قياسه؟","o":["درجة الحرارة بمقياس كلفن، ووحدتها الكلفن K","درجة الحرارة بمقياس سلسيوس، ووحدتها `°C`","كمية الحرارة، ووحدتها الجول J","درجة الحرارة بمقياس فهرنهايت، ووحدتها `°F`"],"a":0,"law":"`K = °C + 273`","w":"K هي درجة الحرارة بمقياس كلفن، ووحدتها الكلفن"},"i":{"q":"من القانون `K = °C + 273`، ما العلاقة بين درجة الحرارة بالكلفن ودرجتها بالسلسيوس؟","o":["كلما زادت إحداهما زادت الأخرى بالمقدار نفسه","كلما زادت إحداهما قلت الأخرى","لا علاقة بينهما","متساويتان دائما"],"a":0,"t":1,"w":"الفرق بين المقياسين ثابت 273، فتزيدان بنفس المقدار"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الحرارة ودرجة الحرارة ومقاييسها في جملة واحدة، فماذا تقول؟","o":["الحرارة طاقة تنتقل تلقائيا من الجسم الساخن إلى البارد ووحدتها الجول، ودرجة الحرارة تقاس بمقاييس سلسيوس وفهرنهايت وكلفن.","الحرارة طاقة تنتقل تلقائيا من الجسم البارد إلى الساخن ووحدتها الجول، ودرجة الحرارة تقاس بمقاييس سلسيوس وفهرنهايت وكلفن.","الحرارة طاقة تنتقل تلقائيا من الجسم الساخن إلى البارد ووحدتها الكلفن، ودرجة الحرارة تقاس بمقاييس سلسيوس وفهرنهايت وكلفن.","الحرارة طاقة تنتقل تلقائيا من الجسم الساخن إلى البارد ووحدتها الجول، ودرجة الحرارة تقاس بمقياس سلسيوس فقط."],"a":0},"x":"law"},"2-3":{"r":{"q":"تنتقل الحرارة تلقائيا:","o":["من الجسم الساخن إلى البارد","من البارد إلى الساخن","بين جسمين متساويين في درجة الحرارة","لا تنتقل"],"a":0,"say":"واليوم نحسب كمية الحرارة التي يحتاجها الجسم لترتفع درجة حرارته.","w":"الحرارة تنتقل تلقائيا من الأعلى حرارة إلى الأقل"},"s":{"q":"أي عبارة تصف قانون كمية الحرارة `Q = m·c·ΔT`؟","o":["كمية الحرارة تساوي الكتلة في الحرارة النوعية في التغير في درجة الحرارة","كمية الحرارة تساوي الكتلة في الحرارة الكامنة في التغير في درجة الحرارة","كمية الحرارة تساوي الكتلة في الحرارة النوعية في درجة الحرارة النهائية","كمية الحرارة تساوي الكتلة في الحرارة النوعية مقسومة على التغير في درجة الحرارة"],"a":0,"law":"Q = m·c·ΔT","w":"الحرارة اللازمة تزيد بزيادة الكتلة والحرارة النوعية والتغير في درجة الحرارة","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون Q = m·c·ΔT، كيف نحسب الحرارة النوعية؟","o":["c = Q / (m·ΔT)","c = Q·m·ΔT","c = m·ΔT / Q","c = Q − m·ΔT"],"a":0,"t":3,"w":"نا نقسم الطرفين على m·ΔT فنحصل على c = Q / (m·ΔT)"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الحرارة النوعية والحرارة الكامنة في جملة واحدة، فماذا تقول؟","o":["الحرارة النوعية ترفع درجة حرارة المادة Q = m·c·ΔT، والحرارة الكامنة تغير حالتها دون تغير درجة حرارتها.","الحرارة النوعية تغير حالة المادة Q = m·c·ΔT، والحرارة الكامنة ترفع درجة حرارتها دون تغير حالتها.","الحرارة النوعية ترفع درجة حرارة المادة Q = m·c·ΔT، والحرارة الكامنة ترفع درجة حرارتها دون تغير حالتها.","الحرارة النوعية ترفع درجة حرارة المادة Q = m·c / ΔT، والحرارة الكامنة تغير حالتها دون تغير درجة حرارتها."],"a":0},"x":"req"},"2-5":{"r":{"q":"في القانون Q = m·c·ΔT، ماذا تمثل c؟","o":["الحرارة النوعية للمادة","السعة الحرارية","كمية الحرارة","درجة الحرارة"],"a":0,"say":"وعندما يتلامس جسمان ساخن وبارد تنتقل الحرارة بينهما حتى الاتزان، وهو موضوع درسنا اليوم.","w":"c في القانون تمثل الحرارة النوعية للمادة"},"s":{"q":"في قانون الاتزان الحراري `m₁c₁(T₁ − Tf) = m₂c₂(Tf − T₂)`، ماذا يمثل الرمز `Tf`، وما وحدة قياسه؟","o":["درجة حرارة الاتزان النهائية، ووحدتها `°C`","درجة حرارة الجسم الساخن، ووحدتها `°C`","درجة حرارة الاتزان، ووحدتها الجول J","كمية الحرارة، ووحدتها `°C`"],"a":0,"law":"m₁c₁(T₁ − Tf) = m₂c₂(Tf − T₂)","w":"Tf هي درجة الحرارة التي يستقر عندها الخليط"},"i":{"q":"من القانون Q = m·c·ΔT، إذا بقيت الكتلة والحرارة النوعية ثابتتين، ما العلاقة بين كمية الحرارة والتغير في درجة الحرارة؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"ΔT في البسط، فكلما زاد التغير في درجة الحرارة زادت كمية الحرارة"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الاتزان الحراري وطرق انتقال الحرارة في جملة واحدة، فماذا تقول؟","o":["عند تلامس جسمين تنتقل الحرارة حتى يصلا إلى درجة واحدة، والحرارة المفقودة تساوي المكتسبة، وتنتقل بالتوصيل والحمل والإشعاع.","عند تلامس جسمين تنتقل الحرارة حتى يصلا إلى درجة واحدة، والحرارة المفقودة أكبر من المكتسبة، وتنتقل بالتوصيل والحمل والإشعاع.","عند تلامس جسمين يبقى كل منهما على درجته، والحرارة المفقودة تساوي المكتسبة، وتنتقل بالتوصيل والحمل والإشعاع.","عند تلامس جسمين تنتقل الحرارة حتى يصلا إلى درجة واحدة، والحرارة المفقودة تساوي المكتسبة، وتنتقل بالتوصيل فقط."],"a":0},"x":"req"},"3-1":{"r":{"q":"في الاتزان الحراري، الحرارة المفقودة من الجسم الساخن:","o":["تساوي الحرارة المكتسبة للبارد","أكبر من المكتسبة","أصغر من المكتسبة","تساوي صفرا"],"a":0,"say":"وكما تنتقل الحرارة بين الأجسام تنتقل الشحنات أيضا، وهي موضوع وحدتنا الجديدة.","w":"الحرارة المفقودة من الساخن تساوي ما يكتسبه البارد"},"s":{"q":"أي عبارة تصف قانون كولوم `F = k·q₁·q₂ / r²`؟","o":["القوة تساوي ثابت كولوم في حاصل ضرب الشحنتين مقسوما على مربع المسافة","القوة تساوي ثابت كولوم في حاصل ضرب الشحنتين مقسوما على المسافة","القوة تساوي ثابت كولوم في حاصل ضرب الشحنتين في مربع المسافة","القوة تساوي ثابت كولوم في مجموع الشحنتين مقسوما على مربع المسافة"],"a":0,"law":"F = k·q₁·q₂ / r²","w":"قوة كولوم تتناسب طرديا مع حاصل ضرب الشحنتين وعكسيا مع مربع المسافة","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون F = k·q₁·q₂ / r²، كيف نحسب الشحنة q₁؟","o":["q₁ = F·r² / (k·q₂)","q₁ = F·k·q₂ / r²","q₁ = k·q₂ / (F·r²)","q₁ = F − k·q₂·r²"],"a":0,"t":3,"w":"نا نضرب الطرفين في r² ثم نقسم على k·q₂ فنحصل على q₁"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الشحنات الكهربائية وقانون كولوم في جملة واحدة، فماذا تقول؟","o":["الشحنات المتشابهة تتنافر والمختلفة تتجاذب، وقوة كولوم تقل كلما زادت المسافة بين الشحنتين.","الشحنات المتشابهة تتجاذب والمختلفة تتنافر، وقوة كولوم تقل كلما زادت المسافة بين الشحنتين.","الشحنات المتشابهة تتنافر والمختلفة تتجاذب، وقوة كولوم تزداد كلما زادت المسافة بين الشحنتين.","الشحنات المتشابهة تتنافر والمختلفة تتجاذب، وقوة كولوم لا تعتمد على المسافة."],"a":0},"x":"req"},"3-3":{"r":{"q":"الشحنات المتشابهة:","o":["تتنافر","تتجاذب","لا تؤثر في بعضها","تتعادل"],"a":0,"say":"والمنطقة حول الشحنة التي يظهر فيها هذا التأثير هي المجال الكهربائي، موضوع درسنا اليوم.","w":"الشحنات المتشابهة تتنافر والمختلفة تتجاذب"},"s":{"q":"في قانون شدة المجال الكهربائي `E = F / q₀`، ماذا يمثل الرمز `E`، وما وحدة قياسه؟","o":["شدة المجال الكهربائي، ووحدتها N/C","شدة المجال الكهربائي، ووحدتها الكولوم C","القوة الكهربائية، ووحدتها N/C","الشحنة، ووحدتها النيوتن N"],"a":0,"law":"E = F / q₀","w":"E هي شدة المجال الكهربائي، وتقاس بالنيوتن لكل كولوم"},"i":{"q":"من القانون E = F / q₀، إذا بقيت شحنة الاختبار ثابتة، ما العلاقة بين شدة المجال والقوة؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"F في البسط، فكلما زادت القوة زادت شدة المجال"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس المجال الكهربائي وخطوطه في جملة واحدة، فماذا تقول؟","o":["المجال الكهربائي المنطقة حول الشحنة التي يظهر فيها تأثيرها، وخطوطه تخرج من الموجبة وتدخل السالبة ولا تتقاطع.","المجال الكهربائي المنطقة حول الشحنة التي يظهر فيها تأثيرها، وخطوطه تخرج من السالبة وتدخل الموجبة ولا تتقاطع.","المجال الكهربائي المنطقة حول الشحنة التي يظهر فيها تأثيرها، وخطوطه تخرج من الموجبة وتدخل السالبة وتتقاطع.","المجال الكهربائي مقدار الشحنة نفسها، وخطوطه تخرج من الموجبة وتدخل السالبة ولا تتقاطع."],"a":0},"x":"inf"},"3-4":{"r":{"q":"خطوط المجال الكهربائي:","o":["تخرج من الشحنة الموجبة وتدخل السالبة","تخرج من السالبة وتدخل الموجبة","تتقاطع دائما","تكون دائرية"],"a":0,"say":"والشحنة في المجال تمتلك طاقة وضع، ومنها نعرف الجهد الكهربائي اليوم.","w":"خطوط المجال تبدأ من الشحنة الموجبة وتنتهي عند السالبة"},"s":{"q":"أي عبارة تصف قانون الجهد الكهربائي `V = PE / q₀`؟","o":["الجهد الكهربائي يساوي طاقة الوضع الكهربائية مقسومة على شحنة الاختبار","الجهد الكهربائي يساوي طاقة الوضع الكهربائية مضروبة في شحنة الاختبار","الجهد الكهربائي يساوي القوة الكهربائية مقسومة على شحنة الاختبار","الجهد الكهربائي يساوي شحنة الاختبار مقسومة على طاقة الوضع الكهربائية"],"a":0,"law":"V = PE / q₀","w":"الجهد الكهربائي طاقة الوضع لكل وحدة شحنة","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون ΔV = W / q₀، كيف نحسب الشغل؟","o":["W = ΔV·q₀","W = ΔV / q₀","W = q₀ / ΔV","W = ΔV − q₀"],"a":0,"t":3,"w":"نا نضرب الطرفين في q₀ فنحصل على W = ΔV·q₀"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس الجهد الكهربائي في جملة واحدة، فماذا تقول؟","o":["الجهد الكهربائي طاقة الوضع لوحدة الشحنة ووحدته الفولت، وفرق الجهد الشغل المبذول لنقل الشحنة مقسوما عليها.","الجهد الكهربائي طاقة الوضع لوحدة الشحنة ووحدته الأمبير، وفرق الجهد الشغل المبذول لنقل الشحنة مقسوما عليها.","الجهد الكهربائي الشحنة مضروبة في طاقة الوضع ووحدته الفولت، وفرق الجهد الشغل المبذول لنقل الشحنة مقسوما عليها.","الجهد الكهربائي طاقة الوضع لوحدة الشحنة ووحدته الفولت، وفرق الجهد لا يرتبط بالشغل."],"a":0},"x":"law"},"3-5":{"r":{"q":"وحدة قياس الجهد الكهربائي هي:","o":["الفولت","الأمبير","الكولوم","الجول"],"a":0,"say":"واليوم نتعرف على المكثف الذي يخزن الشحنة عند فرق جهد معين.","w":"الجهد الكهربائي يقاس بالفولت"},"s":{"q":"في قانون سعة المكثف `C = q / V`، ماذا يمثل الرمز `C`، وما وحدة قياسه؟","o":["سعة المكثف، ووحدتها الفاراد F","سعة المكثف، ووحدتها الكولوم C","الشحنة، ووحدتها الفاراد F","الجهد، ووحدته الفولت V"],"a":0,"law":"C = q / V","w":"C هي سعة المكثف، وتقاس بالفاراد"},"i":{"q":"من القانون C = ε₀·A / d، إذا بقيت المساحة ثابتة، ما العلاقة بين السعة والمسافة بين اللوحين؟","o":["عكسية","طردية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"d في المقام، فكلما زادت المسافة قلت السعة"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس السعة الكهربائية والمكثفات في جملة واحدة، فماذا تقول؟","o":["سعة المكثف النسبة بين شحنته وفرق الجهد بين لوحيه ووحدتها الفاراد، وتزداد كلما قلت المسافة بين اللوحين.","سعة المكثف النسبة بين شحنته وفرق الجهد بين لوحيه ووحدتها الكولوم، وتزداد كلما قلت المسافة بين اللوحين.","سعة المكثف النسبة بين شحنته وفرق الجهد بين لوحيه ووحدتها الفاراد، وتزداد كلما زادت المسافة بين اللوحين.","سعة المكثف حاصل ضرب شحنته في فرق الجهد ووحدتها الفاراد، وتزداد كلما قلت المسافة بين اللوحين."],"a":0},"x":"inf"},"3-6":{"r":{"q":"في المكثف ذي اللوحين المتوازيين، إذا قلت المسافة بين اللوحين فإن السعة:","o":["تزداد","تقل","تبقى ثابتة","تساوي صفرا"],"a":0,"say":"واليوم نوصل عدة مكثفات معا، ونحسب الطاقة المختزنة فيها.","w":"d في المقام في قانون السعة، فإذا قلت المسافة زادت السعة"},"s":{"q":"أي عبارة تصف قانون المكثفات على التوازي `C_total = C₁ + C₂ + C₃`؟","o":["السعة المكافئة على التوازي تساوي مجموع سعات المكثفات","مقلوب السعة المكافئة على التوازي يساوي مجموع مقلوبات السعات","السعة المكافئة على التوازي تساوي حاصل ضرب السعات","السعة المكافئة على التوازي تساوي أصغر السعات"],"a":0,"law":"C_total = C₁ + C₂ + C₃","w":"التوصيل على التوازي يزيد المساحة الكلية للألواح، فتجمع سعات المكثفات","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون q = C·V، كيف نحسب الجهد على المكثف؟","o":["V = q / C","V = q·C","V = C / q","V = q − C"],"a":0,"t":3,"w":"نا نقسم الطرفين على C فنحصل على V = q / C"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس توصيل المكثفات والطاقة المختزنة فيها في جملة واحدة، فماذا تقول؟","o":["على التوالي الشحنة متساوية والسعة المكافئة أصغر من أصغر سعة، وعلى التوازي الجهد متساو والسعة المكافئة مجموع السعات.","على التوالي الجهد متساو والسعة المكافئة مجموع السعات، وعلى التوازي الشحنة متساوية والسعة المكافئة أصغر من أصغر سعة.","على التوالي الشحنة متساوية والسعة المكافئة مجموع السعات، وعلى التوازي الجهد متساو والسعة المكافئة أصغر من أصغر سعة.","على التوالي الشحنة متساوية والسعة المكافئة أصغر من أصغر سعة، وعلى التوازي الشحنة متساوية والسعة المكافئة مجموع السعات."],"a":0},"x":"law"},"4-1":{"r":{"q":"عند توصيل المكثفات على التوازي، الكمية المتساوية على جميعها هي:","o":["الجهد","الشحنة","السعة","الطاقة"],"a":0,"say":"وحين تتحرك الشحنات بانتظام في اتجاه معين يتكون التيار الكهربائي، موضوع وحدتنا الجديدة.","w":"في التوازي تتصل المكثفات بنفس النقطتين، فيتساوى الجهد عليها"},"s":{"q":"في قانون شدة التيار `I = q / t`، ماذا يمثل الرمز `I`، وما وحدة قياسه؟","o":["شدة التيار، ووحدتها الأمبير A","شدة التيار، ووحدتها الفولت V","الشحنة، ووحدتها الأمبير A","الزمن، ووحدته الكولوم C"],"a":0,"law":"I = q / t","w":"I هي شدة التيار، وتقاس بالأمبير"},"i":{"q":"من القانون I = q / t، إذا بقي الزمن ثابتا، ما العلاقة بين شدة التيار والشحنة المارة؟","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"q في البسط، فكلما زادت الشحنة المارة زادت شدة التيار"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس التيار الكهربائي وكثافة التيار وسرعة الانجراف وأنواع التيارات في جملة واحدة، فماذا تقول؟","o":["التيار حركة منتظمة للشحنات، وشدته الشحنة المارة على الزمن ووحدتها الأمبير، والاتجاه الاصطلاحي من الموجب إلى السالب.","التيار حركة منتظمة للشحنات، وشدته الشحنة المارة مضروبة في الزمن ووحدتها الأمبير، والاتجاه الاصطلاحي من الموجب إلى السالب.","التيار حركة منتظمة للشحنات، وشدته الشحنة المارة على الزمن ووحدتها الفولت، والاتجاه الاصطلاحي من الموجب إلى السالب.","التيار حركة منتظمة للشحنات، وشدته الشحنة المارة على الزمن ووحدتها الأمبير، والاتجاه الاصطلاحي هو اتجاه حركة الإلكترونات."],"a":0},"x":"law"},"4-5":{"r":{"q":"شدة التيار الكهربائي هي:","o":["معدل مرور الشحنة عبر مقطع الموصل","عدد الإلكترونات في الموصل","الجهد بين طرفي الموصل","طاقة الشحنة"],"a":0,"say":"والموصل يمانع مرور التيار، وهذه الممانعة هي المقاومة، موضوع درسنا اليوم.","w":"شدة التيار هي كمية الشحنة المارة في وحدة الزمن"},"s":{"q":"أي عبارة تصف قانون أوم `V = I·R`؟","o":["الجهد يساوي شدة التيار في المقاومة","الجهد يساوي شدة التيار مقسومة على المقاومة","المقاومة تساوي الجهد في شدة التيار","شدة التيار تساوي الجهد في المقاومة"],"a":0,"law":"V = I·R","w":"قانون أوم ينص على أن فرق الجهد يساوي حاصل ضرب شدة التيار في المقاومة","h":"اقرأ القانون رمزا رمزا، وانتبه للضرب والقسمة."},"i":{"q":"من القانون V = I·R، كيف نحسب المقاومة؟","o":["R = V / I","R = V·I","R = I / V","R = V − I"],"a":0,"t":3,"w":"نا نقسم الطرفين على I فنحصل على R = V / I"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس المقاومة وقانون أوم والقدرة الكهربائية في جملة واحدة، فماذا تقول؟","o":["المقاومة ممانعة الموصل لمرور التيار ووحدتها الأوم، وقانون أوم V = I·R.","المقاومة ممانعة الموصل لمرور التيار ووحدتها الأمبير، وقانون أوم V = I·R.","المقاومة سرعة مرور التيار في الموصل ووحدتها الأوم، وقانون أوم V = I·R.","المقاومة ممانعة الموصل لمرور التيار ووحدتها الأوم، وقانون أوم V = I / R."],"a":0},"x":"req"},"4-8":{"r":{"q":"في قانون أوم V = I·R، عند ثبات المقاومة تكون العلاقة بين الجهد والتيار:","o":["طردية","عكسية","لا علاقة بينهما","ثابتة"],"a":0,"say":"واليوم نوصل عدة مقاومات معا، ونحسب المقاومة المكافئة.","w":"عند ثبات R يزيد الجهد بزيادة التيار بنفس النسبة"},"s":{"q":"في قانون المقاومات على التوالي `R_total = R₁ + R₂ + R₃`، ماذا يمثل الرمز `R_total`، وما وحدة قياسه؟","o":["المقاومة المكافئة، ووحدتها الأوم Ω","المقاومة المكافئة، ووحدتها الأمبير A","التيار الكلي، ووحدته الأوم Ω","الجهد الكلي، ووحدته الفولت V"],"a":0,"law":"R_total = R₁ + R₂ + R₃","w":"R_total هي المقاومة المكافئة، وتقاس بالأوم"},"i":{"q":"من قانون أوم V = I·R في دائرة التوالي، إذا بقي الجهد ثابتا وزادت المقاومة المكافئة، ما العلاقة بين التيار والمقاومة؟","o":["عكسية","طردية","لا علاقة بينهما","ثابتة"],"a":0,"t":1,"w":"I = V / R، فعند ثبات الجهد يقل التيار كلما زادت المقاومة"},"m":{"q":"لو طلب منك زميلك أن تشرح له درس توصيل المقاومات على التوالي والتوازي في جملة واحدة، فماذا تقول؟","o":["على التوالي التيار واحد والمقاومة المكافئة مجموع المقاومات، وعلى التوازي الجهد واحد والمقاومة المكافئة أصغر من أصغر مقاومة.","على التوالي الجهد واحد والمقاومة المكافئة مجموع المقاومات، وعلى التوازي التيار واحد والمقاومة المكافئة أصغر من أصغر مقاومة.","على التوالي التيار واحد والمقاومة المكافئة مجموع المقاومات، وعلى التوازي الجهد واحد والمقاومة المكافئة أكبر من أكبر مقاومة.","على التوالي التيار واحد والمقاومة المكافئة أصغر من أصغر مقاومة، وعلى التوازي الجهد واحد والمقاومة المكافئة مجموع المقاومات."],"a":0},"x":"law"}};
