window.COACHTOP={"0-1":[["الكميات الفيزيائية",["الكميات الأساسية والكميات المشتقة"]],["أنظمة القياس",["أجزاء ومضاعفات وحدات القياس"]]],"0-2":[["التحويل بين وحدات القياس",[]],["استخدام الوحدات للتأكد من صحة القوانين",[]]],"0-4":[["الكميات القياسية",[]],["الكميات المتجهة",[]],["إيجاد محصلة متجهين وقانون جيب التمام",[]]],"0-5":[["تحليل الكميات المتجهة",[]]],"0-6":[["متجهات الوحدة",[]],["ضرب الكميات المتجهة",["الضرب القياسي (العددي)","الضرب الاتجاهي"]]],"1-1":[["الحركة على خط مستقيم",["المسافة والإزاحة","السرعة المتوسطة","التسارع"]]],"1-2":[["معادلات الحركة على خط مستقيم وبتسارع ثابت",[]]],"1-3":[["مفهوم القوة",[]],["قوانين نيوتن للحركة",["قانون نيوتن الأول","قانون نيوتن الثاني","قانون نيوتن الثالث"],"قانون نيوتن الأول والثاني والثالث"]],"1-5":[["الاحتكاك",[]]],"1-7":[["الشغل",[]]],"1-8":[["الطاقة",["الطاقة الحركية","الطاقة الكامنة (طاقة الوضع)"]]],"1-9":[["مبدأ قانون حفظ الطاقة",[]]],"2-1":[["الحرارة ودرجة الحرارة",[]],["مقاييس درجات الحرارة",["مقياس كلفن","مقياس فهرنهايت","المقياس المئوي","معادلات التحويل بينها"]]],"2-3":[["الحرارة النوعية",[]],["الحرارة الكامنة",[]]],"2-5":[["الاتزان الحراري",[]],["طرق انتقال الحرارة",[]]],"3-1":[["الكهرباء الساكنة",["أنواع الشحنات","انتقال الشحنات","طرق شحن الأجسام بالكهرباء الساكنة"]],["قانون كولوم",[]]],"3-3":[["المجال الكهربائي",["خطوط المجال","شدة المجال الكهربائي والمجال الكهربائي عند نقطة"]]],"3-4":[["الجهد الكهربائي",[]]],"3-5":[["السعة الكهربائية",["المكثف ذو اللوحين المتوازيين","استخدامات المكثفات"],"المكثف ذي اللوحين المتوازيين واستخدامات المكثفات"]],"3-6":[["توصيل المكثفات",["التوصيل على التوازي","التوصيل على التوالي"]],["الطاقة المختزنة في المكثف",[]]],"4-1":[["التيار الكهربائي",["كثافة التيار","سرعة الانجراف","أنواع التيارات الكهربائية"]]],"4-5":[["المقاومة",["قانون أوم","العوامل المؤثرة في مقاومة أي موصل","المقاومة النوعية","العلاقة بين المقاومة ودرجة الحرارة"]],["القدرة الكهربائية",[]]],"4-8":[["توصيل المقاومات",["التوصيل على التوالي","التوصيل على التوازي"]]]};
